function base64UrlToBytes(value:string){const padded=value.replace(/-/g,'+').replace(/_/g,'/');const raw=atob(padded+'='.repeat((4-padded.length%4)%4));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
async function enableBiometricLock(){if(!s?.user?.id)return;if(!window.PublicKeyCredential||!navigator.credentials)return flash('This browser does not support device biometric sign-in. Try an updated browser on a device with fingerprint or face unlock.');setBiometricBusy(true);try{const challenge=crypto.getRandomValues(new Uint8Array(32));const userId=new TextEncoder().encode(s.user.id).slice(0,64);const credential=await navigator.credentials.create({publicKey:{challenge,rp:{name:'Globalvest',id:location.hostname},user:{id:userId,name:s.user.email||s.user.id,displayName:p?.full_name||s.user.email||'Globalvest user'},pubKeyCredParams:[{type:'public-key',alg:-7},{type:'public-key',alg:-257}],authenticatorSelection:{authenticatorAttachment:'platform',residentKey:'preferred',userVerification:'required'},timeout:60000,attestation:'none'}}) as PublicKeyCredential|null;if(!credential)throw new Error('Biometric setup was cancelled.');localStorage.setItem('globalvest-biometric-credential:'+s.user.id,credential.id);setBiometricReady(true);flash('Device biometric screen lock enabled on this device.');}catch(e:any){flash(e?.message||'Could not enable device biometric lock.')}finally{setBiometricBusy(false)}}
async function unlockBiometricScreen(){if(!s?.user?.id)return;const id=localStorage.getItem('globalvest-biometric-credential:'+s.user.id);if(!id)return flash('No biometric credential is saved on this device.');setBiometricBusy(true);try{const assertion=await navigator.credentials.get({publicKey:{challenge:crypto.getRandomValues(new Uint8Array(32)),rpId:location.hostname,allowCredentials:[{type:'public-key',id:base64UrlToBytes(id)}],userVerification:'required',timeout:60000}});if(!assertion)throw new Error('Biometric verification was cancelled.');setScreenLocked(false)}catch(e:any){flash(e?.message||'Biometric verification failed.')}finally{setBiometricBusy(false)}}

