async function saveProfile(){const name=profileFullName.trim(),nation=profileCountry.trim();if(!name||!nation){flash('Enter your full name and country before saving.');return}setProfileSaving(true);const r=await sb.from('profiles').update({full_name:name,country:nation}).eq('id',s.user.id);setProfileSaving(false);if(r.error){flash('Could not save profile: '+r.error.message);return}setP((old:any)=>({...old,full_name:name,country:nation}));flash('Saved successfully');}
async function sendPasswordCode(){const target=String(s?.user?.email||'').trim();if(!target)return flash('Your account does not have an email address.');setPasswordCodeSending(true);try{const r=await sb.auth.signInWithOtp({email:target,options:{shouldCreateUser:false}});if(r.error)throw r.error;setPasswordCodeSent(true);setPasswordCode('');flash('A verification code has been requested for '+target+'. Check your inbox and spam folder.')}catch(e:any){flash('Could not send password verification code: '+(e?.message||'Please try again.'))}finally{setPasswordCodeSending(false)}}async function saveNewPassword(){if(!passwordCodeSent)return flash('Request a verification code first.');if(!/^\d{6}$/.test(passwordCode.trim()))return flash('Enter the 6-digit verification code sent to your email.');if(newPassword.length<8)return flash('Your new password must contain at least 8 characters.');if(newPassword!==confirmPassword)return flash('The new passwords do not match.');setPasswordSaving(true);try{const emailAddress=String(s?.user?.email||'').trim();const verified=await sb.auth.verifyOtp({email:emailAddress,token:passwordCode.trim(),type:'email'});if(verified.error)throw verified.error;const changed=await sb.auth.updateUser({password:newPassword});if(changed.error)throw changed.error;setS((old:any)=>old?({...old,user:changed.data.user||old.user}):old);setPasswordCode('');setNewPassword('');setConfirmPassword('');setPasswordCodeSent(false);flash('Your password has been changed successfully.')}catch(e:any){flash('Password change failed: '+(e?.message||'The code may have expired. Request a new code and try again.'))}finally{setPasswordSaving(false)}}
async function loadSupportTickets(){const r=await sb.from('support_tickets').select('*').order('created_at',{ascending:false});if(r.error){flash('Could not load support tickets: '+r.error.message);return}setSupportTickets(r.data||[])}
async function loadSupportMessages(ticketId:string){const r=await sb.from('support_ticket_messages').select('*').eq('ticket_id',ticketId).order('created_at',{ascending:true});if(r.error){console.error('Support chat load failed',r.error);return}setSupportChatMessages((old:any)=>({...old,[ticketId]:r.data||[]}))}
async function uploadSupportImage(file:File,ticketId:string){if(!file.type.startsWith('image/'))throw new Error('Only image uploads are supported.');if(file.size>5*1024*1024)throw new Error('Images must be 5 MB or smaller.');const safe=file.name.replace(/[^a-zA-Z0-9._-]/g,'_');const path=s.user.id+'/'+ticketId+'/'+Date.now()+'-'+safe;const up=await sb.storage.from('support-attachments').upload(path,file,{upsert:false,contentType:file.type});if(up.error)throw up.error;return path}
async function openSupportImage(path:string){const r=await sb.storage.from('support-attachments').createSignedUrl(path,3600);if(r.error){flash('Could not open attachment: '+r.error.message);return}window.open(r.data.signedUrl,'_blank','noopener,noreferrer')}
async function sendSupportMessage(ticketId:string){const body=String(supportChatDrafts[ticketId]||'').trim(),file=supportChatFiles[ticketId] as File|null;if(!body&&!file)return flash('Write a message or attach an image.');setSupportChatSending(ticketId);try{let attachment_path:string|null=null;if(file)attachment_path=await uploadSupportImage(file,ticketId);const r=await sb.from('support_ticket_messages').insert({ticket_id:ticketId,user_id:s.user.id,sender_role:isAdmin?'admin':'user',body,attachment_path});if(r.error)throw r.error;setSupportChatDrafts((old:any)=>({...old,[ticketId]:''}));setSupportChatFiles((old:any)=>({...old,[ticketId]:null}));await loadSupportMessages(ticketId);await loadSupportTickets()}catch(e:any){flash('Could not send message: '+(e?.message||'Please try again.'))}finally{setSupportChatSending(null)}}
async function submitSupportTicket(){const subject=supportSubject.trim(),body=supportMessage.trim();if(subject.length<3||body.length<5){flash('Please enter a subject and a message with at least 5 characters.');return}setSupportSubmitting(true);const ticketId=crypto.randomUUID();try{let attachment_path:string|null=null;if(supportAttachment)attachment_path=await uploadSupportImage(supportAttachment,ticketId);const r=await sb.from('support_tickets').insert({id:ticketId,user_id:s.user.id,subject,category:supportCategory,priority:supportPriority,message:body,attachment_path}).select().single();if(r.error)throw r.error;setSupportSubject('');setSupportCategory('General');setSupportPriority('normal');setSupportMessage('');setSupportAttachment(null);setSupportChatTicket(ticketId);flash('Support ticket created. Continue the conversation in live chat.');await loadSupportTickets();await loadSupportMessages(ticketId)}catch(e:any){flash('Could not submit support request: '+(e?.message||'Please try again.'))}finally{setSupportSubmitting(false)}}
async function replyToSupportTicket(id:string){const reply=String(supportReplies[id]||'').trim();if(!reply)return flash('Enter a reply first.');const r=await sb.from('support_tickets').update({admin_reply:reply,status:'waiting_for_user',updated_at:new Date().toISOString()}).eq('id',id);if(r.error){flash('Could not send reply: '+r.error.message);return}flash('Reply sent successfully.');await loadSupportTickets()}
