async function login(){setMessage('');const r=await sb.auth.signInWithPassword({email,password});if(r.error){const msg=String(r.error.message||'');if(/invalid login credentials/i.test(msg)){flash('Email or password is incorrect. If you had an account before the migration, sign up again with the same email address. Your old password cannot be used.');}else if(/email not confirmed/i.test(msg)){flash('Please verify your email address before signing in. Check your inbox for the verification code.');}else{flash(msg)}return}setEmail('');setPassword('');setMessage('');if(r.data.session){setS(r.data.session);await load(r.data.session.user.id)}}async function signup(){setMessage('');if(!fullName.trim()||!country.trim()||!email||password.length<6)return flash('Enter your full name, country, email and a password of at least 6 characters.');const r=await sb.auth.signUp({email,password,options:{data:{full_name:fullName.trim(),country:country.trim()}}});if(r.error)return flash(r.error.message);if(r.data.session){setS(r.data.session);await load(r.data.session.user.id);setAwaitingVerification(false);flash('Account created successfully.');return}setAwaitingVerification(true);setVerificationCode('');flash('Check your email for the signup verification code, then enter it below. If no code arrives, check spam or ask the administrator to verify the Supabase email template and SMTP settings.');setPassword('');}async function verifySignupCode(){setMessage('');if(!email||verificationCode.trim().length<6)return flash('Enter the verification code sent to your email.');const r=await sb.auth.verifyOtp({email,token:verificationCode.trim(),type:'signup'});if(r.error)return flash('Verification failed: '+r.error.message);if(r.data.session){setS(r.data.session);await load(r.data.session.user.id);setAwaitingVerification(false);setVerificationCode('');setEmail('');setPassword('');setFullName('');setCountry('');flash('Email verified successfully. Welcome to Globalvest.')}}async function invest(){if(p?.kyc_status!=='verified'){setView('KYC');return flash('Please verify your identity first before making an investment.')}const n=Number(amount);if(!selected||!Number.isFinite(n)||n<=0)return setMessage('Enter a valid investment amount.');if(n<Number(selected.min_amount))return setMessage('Amount is below the minimum investment.');const r=await sb.rpc('create_investment',{p_product_id:selected.id,p_currency:selected.currency,p_amount:n});flash(r.error?.message||'Investment created successfully');if(!r.error){void sendAccountEmail('investment_created',s.user.id,{amount:n,currency:selected.currency,product:selected.name,event_id:String(r.data?.id||'investment-'+Date.now())});setSelected(null);setAmount('');await load(s.user.id);setView('Portfolio')}}
